quiz.setup:
const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim()).filter((s) => s !== "");

// wait(ms, label) を書く

// 各行の wait を同時に始め、終わった順にラベルを出す
// 全部終わったら「全部終わった」を出す

quiz.answer:
const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim()).filter((s) => s !== "");

function wait(ms, label) {
  return new Promise((resolve) => setTimeout(() => resolve(label), ms));
}

const jobs = lines.map((line) => {
  const [ms, label] = line.split(" ");
  return wait(Number(ms), label).then((v) => console.log(v));
});
Promise.all(jobs).then(() => console.log("全部終わった"));

