quiz.answer:
const lines = require("fs").readFileSync(0, "utf8").split("\n").map((s) => s.trim()).filter((s) => s !== "");

function checkAge(n) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (n >= 0) resolve(`${n}歳`);
      else reject(new Error("年齢が負です"));
    }, 10);
  });
}

async function main() {
  for (const line of lines) {
    try {
      const v = await checkAge(Number(line));
      console.log("OK", v);
    } catch (e) {
      console.log("NG", e.message);
    }
  }
}
main();
